import{_ as o,o as a,c as e,ag as r}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"如何处理情绪","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-情绪.md","filePath":"20-专题研究/topic-情绪.md","lastUpdated":1778040484000}'),l={name:"20-专题研究/topic-情绪.md"};function u(h,t,i,n,q,d){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="如何处理情绪" tabindex="-1">如何处理情绪 <a class="header-anchor" href="#如何处理情绪" aria-label="Permalink to &quot;如何处理情绪&quot;">​</a></h1><blockquote><p>专题分析：情绪的智慧管理 组合模型：对境不住 + 历境炼心 + 圆融中和</p></blockquote><hr><h2 id="一、情绪的本质" tabindex="-1">一、情绪的本质 <a class="header-anchor" href="#一、情绪的本质" aria-label="Permalink to &quot;一、情绪的本质&quot;">​</a></h2><p>了空居士对情绪的根本看法：<strong>情绪不是敌人，烦恼是觉悟的种子</strong>。</p><blockquote><p><strong>&quot;烦恼即菩提——烦恼不是敌人，它是你修行的机会。每一次烦恼来的时候，就是你进步的契机。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></p><blockquote><p><strong>&quot;一切烦恼为如来种——烦恼是觉悟的种子，不是敌人。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></p><ul><li><strong>对境不住</strong>：情绪是对&quot;境&quot;的自动反应——关键是<strong>知道情绪，但不被情绪带走</strong></li><li><strong>历境炼心</strong>：每一次情绪波动都是修行的机会</li><li><strong>圆融中和</strong>：不压抑也不放纵，在中间找到智慧的平衡</li></ul><hr><h2 id="二、对治三种常见情绪" tabindex="-1">二、对治三种常见情绪 <a class="header-anchor" href="#二、对治三种常见情绪" aria-label="Permalink to &quot;二、对治三种常见情绪&quot;">​</a></h2><h3 id="_1-愤怒" tabindex="-1">1. 愤怒 <a class="header-anchor" href="#_1-愤怒" aria-label="Permalink to &quot;1. 愤怒&quot;">​</a></h3><blockquote><p><strong>&quot;被人骂时，试着用旁观者的心态——&#39;他为什么这么激动？&#39;而不是&#39;他在骂我！&#39;&quot;</strong></p></blockquote><p>— 答疑精选</p><blockquote><p><strong>&quot;保持平静的要诀就是保持理智地去看待一切。不平静的时候问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></p><h3 id="_2-悲伤" tabindex="-1">2. 悲伤 <a class="header-anchor" href="#_2-悲伤" aria-label="Permalink to &quot;2. 悲伤&quot;">​</a></h3><blockquote><p><strong>&quot;过去心不可得，现在心不可得，未来心不可得。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p><p>知道自己在悲伤，但不让悲伤变成&quot;我的人生就是苦的&quot;这种整体判断。</p><h3 id="_3-嫉妒" tabindex="-1">3. 嫉妒 <a class="header-anchor" href="#_3-嫉妒" aria-label="Permalink to &quot;3. 嫉妒&quot;">​</a></h3><blockquote><p><strong>&quot;随喜是众善奉行的第一步。看到别人做好事，心生欢喜，这就是随喜。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经11分-随喜即众善">金刚经11分-随喜即众善</a></p><p>别人好→随喜（为他高兴）。别人好≠我不好。别人的成功可以激励我，而不是打击我。</p><hr><h2 id="三、实操方法" tabindex="-1">三、实操方法 <a class="header-anchor" href="#三、实操方法" aria-label="Permalink to &quot;三、实操方法&quot;">​</a></h2><p>了空居士给出的三步：觉察→理智→行动。</p><blockquote><p><strong>&quot;不怕念起，只怕觉迟。走神了——让走神，知道走神就不走神。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/答疑2021-不怕念起只怕觉迟">答疑2021-不怕念起只怕觉迟</a>（觉察）</p><blockquote><p><strong>&quot;保持平静的要诀就是保持理智地去看待一切。不平静的时候问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a>（理智分析）</p><blockquote><p><strong>&quot;烦恼来了，不是压制它，也不是随它去。是——看清楚它，然后做该做的事。&quot;</strong></p></blockquote><p>— 答疑精选（行动）</p><hr><h2 id="四、不要压制情绪" tabindex="-1">四、不要压制情绪 <a class="header-anchor" href="#四、不要压制情绪" aria-label="Permalink to &quot;四、不要压制情绪&quot;">​</a></h2><blockquote><p><strong>&quot;最清净的人就是死人。第二清净的人就是老人痴呆症。&quot;</strong></p></blockquote><p>— 答疑精选</p><blockquote><p><strong>&quot;真正清净，是正确地看待现实，正确地面对现实——你的心就平静面对现实。&quot;</strong></p></blockquote><p>— 答疑精选</p><p>修行不是变成没有感情的木头人，而是<strong>情绪来了你能觉察、能管理、能转化</strong>。</p><hr><h2 id="五、常见误解" tabindex="-1">五、常见误解 <a class="header-anchor" href="#五、常见误解" aria-label="Permalink to &quot;五、常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>修行人没有情绪</td><td>&quot;最清净的人就是死人&quot;——情绪是正常的，关键是觉察</td><td>答疑精选</td></tr><tr><td>情绪来了要压住</td><td>&quot;不怕念起，只怕觉迟&quot;——不是压，是觉察</td><td><a href="/60-原文段落/答疑2021-不怕念起只怕觉迟">答疑2021-不怕念起只怕觉迟</a></td></tr><tr><td>有了情绪说明修行差</td><td>&quot;烦恼即菩提&quot;——情绪是修行的机会</td><td><a href="/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></td></tr></tbody></table><hr><h2 id="六、推荐模型" tabindex="-1">六、推荐模型 <a class="header-anchor" href="#六、推荐模型" aria-label="Permalink to &quot;六、推荐模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 觉察情绪，不被带走</li><li><a href="/10-核心模型/model-历境炼心">历境炼心</a> — 情绪是修行的机会</li><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 不走极端，不压抑不放纵</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-烦恼">dict-烦恼</a> — 烦恼是觉悟的种子</li><li><a href="/50-概念资料/dict-观照">dict-观照</a> — 观察情绪的具体方法</li><li><a href="/50-概念资料/dict-清净心">dict-清净心</a> — 不是没有情绪，是正确地面对现实</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（全部原话添加原文段落链接，新增常见误解表，新增概念链接） 来源：金刚经、答疑专辑2014/2019</p></blockquote>',51)])])}const c=o(l,[["render",u]]);export{s as __pageData,c as default};
